package android.graphics;
public class PathMeasure {
 private float[] xy=new float[0]; private float length;
 public PathMeasure(){} public PathMeasure(Path p,boolean close){setPath(p,close);} public void setPath(Path p,boolean close){if(p==null){xy=new float[0];length=0;return;} String[] s=p.indroidPath().split(" ");float[] out=new float[s.length*22];int i=0,n=0;float x=0,y=0,sx=0,sy=0;while(i<s.length){String c=s[i++];if(c.length()==0)continue;int count=c.equals("C")?6:c.equals("Q")?4:c.equals("Z")?0:2;float[] a=new float[count];for(int j=0;j<count;j++)a[j]=Float.parseFloat(s[i++]);if(c.equals("Z")){out[n++]=sx;out[n++]=sy;x=sx;y=sy;}else if(c.equals("M")||c.equals("L")){x=a[0];y=a[1];out[n++]=x;out[n++]=y;if(c.equals("M")){sx=x;sy=y;}}else {float ox=x,oy=y;for(int j=1;j<=20;j++){float t=j/20f,u=1-t;if(count==4){x=u*u*ox+2*u*t*a[0]+t*t*a[2];y=u*u*oy+2*u*t*a[1]+t*t*a[3];}else{x=u*u*u*ox+3*u*u*t*a[0]+3*u*t*t*a[2]+t*t*t*a[4];y=u*u*u*oy+3*u*u*t*a[1]+3*u*t*t*a[3]+t*t*t*a[5];}out[n++]=x;out[n++]=y;}}}if(close&&n>=2){out[n++]=sx;out[n++]=sy;}xy=new float[n];for(i=0;i<n;i++)xy[i]=out[i];length=0;for(i=2;i<n;i+=2)length+=PointF.length(xy[i]-xy[i-2],xy[i+1]-xy[i-1]);} public float getLength(){return length;} public boolean getPosTan(float distance,float[] pos,float[] tan){if(length==0)return false;distance=Math.max(0,Math.min(length,distance));for(int i=2;i<xy.length;i+=2){float dx=xy[i]-xy[i-2],dy=xy[i+1]-xy[i-1],d=PointF.length(dx,dy);if(d>0&&(distance<=d||i==xy.length-2)){float f=distance/d;if(pos!=null){pos[0]=xy[i-2]+dx*f;pos[1]=xy[i-1]+dy*f;}if(tan!=null){tan[0]=dx/d;tan[1]=dy/d;}return true;}distance-=d;}return false;} public boolean getSegment(float start,float stop,Path dst,boolean move){start=Math.max(0,start);stop=Math.min(length,stop);if(start>=stop)return false;float[] p=new float[2];getPosTan(start,p,null);if(move)dst.moveTo(p[0],p[1]);else dst.lineTo(p[0],p[1]);float d=0;for(int i=2;i<xy.length;i+=2){d+=PointF.length(xy[i]-xy[i-2],xy[i+1]-xy[i-1]);if(d>start&&d<stop)dst.lineTo(xy[i],xy[i+1]);}getPosTan(stop,p,null);dst.lineTo(p[0],p[1]);return true;} public boolean nextContour(){return false;} public boolean isClosed(){return xy.length>=4&&xy[0]==xy[xy.length-2]&&xy[1]==xy[xy.length-1];}
}
